from collections.abc import AsyncGenerator
from datetime import UTC
from datetime import datetime
from datetime import timedelta
import json
import logging

from vss_agents.tools.embed_search import VisionLLM

from fastapi import HTTPException
from langchain_core.messages import HumanMessage
from langchain_core.messages import SystemMessage
from nat.builder.builder import Builder
from nat.builder.framework_enum import LLMFrameworkEnum
from nat.builder.function_info import FunctionInfo
from nat.cli.register_workflow import register_function
from nat.data_models.api_server import ChatRequest  # type: ignore[import-untyped]
from nat.data_models.api_server import ChatResponse  # type: ignore[import-untyped]
from nat.data_models.api_server import ChatResponseChunk  # type: ignore[import-untyped]
from nat.data_models.api_server import Usage
from nat.data_models.component_ref import FunctionRef  # type: ignore[import-untyped]
from nat.data_models.component_ref import LLMRef
from nat.data_models.function import FunctionBaseConfig
from pydantic import BaseModel
from pydantic import ConfigDict
from pydantic import Field

logger = logging.getLogger(__name__)


class SearchConfig(FunctionBaseConfig, name="search"):  # type: ignore[call-arg,misc]
    """Configuration for the Search tool."""

    embed_search_tool: FunctionRef = Field(
        ...,
        description="The function reference of the embed search tool to use.",
    )

    agent_mode_llm: LLMRef = Field(
        ...,
        description="The name of the LLM to use for the search tool to analyze/decompose the input query and fill in parameters if agent_mode is True",
    )

    agent_mode_prompt: str = Field(
        default="""Analyze the user's query and extract search parameters. Return a JSON object with the following optional fields:
- query: The main search query text (required)
- video_names: List of video names/sensor names mentioned (optional, array of strings)
- description: Location or category description mentioned (optional, string)
- timestamp_start: Start time in ISO format (optional, string like "2025-01-01T13:00:00Z")
- timestamp_end: End time in ISO format (optional, string like "2025-01-01T14:00:00Z")
- top_k: Number of results requested (optional, integer, default 5)
- min_cosine_similarity: Minimum similarity threshold (optional, float, default 0.0)

For uploaded videos, use 2025-01-01T00:00:00Z as the base date. Extract time references relative to this base.
Example: "a person pushing a cart in endeavor heart from 1pm to 2pm" should return:
{"query": "a person pushing a cart", "description": "endeavor heart", "timestamp_start": "2025-01-01T13:00:00Z", "timestamp_end": "2025-01-01T14:00:00Z"}

Return only valid JSON, no additional text.""",
        description="Prompt for the agent(LLM) to analyze/decompose the input query and fill in parameters if agent_mode is True",
    )


class SearchInput(BaseModel):
    """Input for the Search tool"""

    model_config = ConfigDict(extra="forbid")

    query: str = Field(
        ...,
        description="Description of the item to search from",
    )

    video_names: list[str] | None = Field(
        default=None,
        description="A list of video names to search from. In DevEx, these are VST sensor-names. Defaults to search from all videos.",
    )

    description: str | None = Field(
        default=None,
        description="Description of video's metadata data, for example, the location of the camera, the category of videos. Defaults to match all descriptions.",
    )

    timestamp_start: datetime | None = Field(
        default=None,
        description="Start time of the video, ISO timestamp. Note for uploaded videos, as a convention, we use 2025-01-01T00:00:00 as the start time.",
    )

    timestamp_end: datetime | None = Field(
        default=None,
        description="End time of the video, ISO timestamp. Note for uploaded videos, as a convention, we use 2025-01-01T00:00:00 as the start time.",
    )

    top_k: int | None = Field(
        default=None,
        description="Number of returned videos. If not provided, returns all matching results.",
    )

    min_cosine_similarity: float = Field(
        default=0.0,
        description="Minimum cosine similarity to filter the results. Default is 0.",
    )

    # Whether or not backend shall use an agent(LLM) to analyze/decompose the input query and fill in parameters.
    # for example. "a person pushing a cart in endeavor heart from 1pm to 2pm" will be decomposed into:
    # {"query: "a person pushing a cart",
    #  "description": "endeavor heart",
    #  "start_time": "2025-12-12T13:00:00.000Z",
    #  "end_time": "2025-12-12T14:00:00.000Z"
    # }
    agent_mode: bool = Field(
        ...,
        description="Whether or not backend shall use an agent(LLM) to analyze/decompose the input query and fill in parameters",
    )


class SearchResult(BaseModel):
    """A single search result item"""

    video_name: str = Field(
        ...,
        description="Name of the video",
    )
    description: str = Field(
        ...,
        description="Description of the video",
    )
    start_time: str = Field(
        ...,
        description="Start time of the video in ISO timestamp format",
    )
    end_time: str = Field(
        ...,
        description="End time of the video in ISO timestamp format",
    )
    video_url: str = Field(
        ...,
        description="URL to access the video",
    )
    screenshot_url: str = Field(
        ...,
        description="URL to access the screenshot",
    )
    similarity: float = Field(
        ...,
        description="Cosine similarity score",
    )


class SearchOutput(BaseModel):
    """Output for the Search tool"""

    model_config = ConfigDict(extra="forbid")

    data: list[SearchResult] = Field(
        default_factory=list,
        description="List of search results matching the query",
    )


@register_function(config_type=SearchConfig, framework_wrappers=[LLMFrameworkEnum.LANGCHAIN])
async def search(config: SearchConfig, _builder: Builder) -> AsyncGenerator[FunctionInfo]:
    # Call embed_search
    embed_search = await _builder.get_function(config.embed_search_tool)

    # Get LLM for agent_mode if needed
    agent_llm = None
    if config.agent_mode_prompt:
        agent_llm = await _builder.get_llm(config.agent_mode_llm, wrapper_type=LLMFrameworkEnum.LANGCHAIN)

    async def _search(search_input: SearchInput) -> SearchOutput:
        """
        Search for videos based on a query with optional filters.
        Input:
            search_input: SearchInput

        Returns:
            SearchOutput: Search results matching the query.
        """
        # If agent_mode is enabled, use LLM to extract parameters from query
        if search_input.agent_mode and agent_llm:
            try:
                # Format prompt with user query
                prompt = f"{config.agent_mode_prompt}\n\nUser query: {search_input.query}"

                # Call LLM to extract parameters
                messages = [
                    SystemMessage(
                        content="You are a helpful assistant that extracts search parameters from natural language queries."
                    ),
                    HumanMessage(content=prompt),
                ]
                llm_response = await agent_llm.ainvoke(messages)
                response_content = llm_response.content if hasattr(llm_response, "content") else str(llm_response)

                # Parse JSON response
                try:
                    # Try to extract JSON from response (handle markdown code blocks)
                    response_text = response_content.strip()
                    if "```json" in response_text:
                        start = response_text.find("```json") + 7
                        end = response_text.find("```", start)
                        if end != -1:
                            response_text = response_text[start:end].strip()
                        else:
                            # No closing marker found, use from start to end
                            response_text = response_text[start:].strip()
                    elif "```" in response_text:
                        start = response_text.find("```") + 3
                        end = response_text.find("```", start)
                        if end != -1:
                            response_text = response_text[start:end].strip()
                        else:
                            # No closing marker found, use from start to end
                            response_text = response_text[start:].strip()

                    extracted_params = json.loads(response_text)

                    # Update search_input with extracted parameters (only if not already set)
                    if isinstance(extracted_params, dict):
                        if extracted_params.get("query"):
                            search_input.query = extracted_params["query"]
                        if extracted_params.get("video_names"):
                            search_input.video_names = (
                                extracted_params["video_names"]
                                if isinstance(extracted_params["video_names"], list)
                                else [extracted_params["video_names"]]
                            )
                        if extracted_params.get("description"):
                            search_input.description = extracted_params["description"]
                        if extracted_params.get("timestamp_start"):
                            try:
                                search_input.timestamp_start = datetime.fromisoformat(
                                    extracted_params["timestamp_start"].replace("Z", "+00:00")
                                )
                            except Exception as e:
                                logger.warning(f"Failed to parse extracted timestamp_start: {e}")
                        if extracted_params.get("timestamp_end"):
                            try:
                                search_input.timestamp_end = datetime.fromisoformat(
                                    extracted_params["timestamp_end"].replace("Z", "+00:00")
                                )
                            except Exception as e:
                                logger.warning(f"Failed to parse extracted timestamp_end: {e}")
                        if extracted_params.get("top_k"):
                            try:
                                search_input.top_k = int(extracted_params["top_k"])
                            except (ValueError, TypeError) as e:
                                logger.debug(f"Failed to parse extracted top_k: {e}")
                        if (
                            "min_cosine_similarity" in extracted_params
                            and extracted_params["min_cosine_similarity"] is not None
                        ):
                            try:
                                search_input.min_cosine_similarity = float(extracted_params["min_cosine_similarity"])
                            except (ValueError, TypeError) as e:
                                logger.debug(f"Failed to parse extracted min_cosine_similarity: {e}")
                except json.JSONDecodeError as e:
                    logger.warning(f"Failed to parse LLM response as JSON: {response_content}, error: {e}")
            except Exception as e:
                logger.error(f"Error in agent_mode parameter extraction: {e}", exc_info=True)
                # Continue with original search_input if extraction fails

        # Convert SearchInput to QueryInput format for embed_search
        query_params = {
            "query": search_input.query,
            "min_cosine_similarity": str(search_input.min_cosine_similarity),
        }

        # Only include top_k if provided (otherwise embed_search returns all results)
        if search_input.top_k is not None:
            query_params["top_k"] = str(search_input.top_k)

        if search_input.video_names and len(search_input.video_names) > 0:
            # Pass video_names as JSON string array
            query_params["video_names"] = json.dumps(search_input.video_names)

        if search_input.description:
            query_params["description"] = search_input.description

        if search_input.timestamp_start:
            query_params["timestamp_start"] = search_input.timestamp_start.isoformat()

        if search_input.timestamp_end:
            query_params["timestamp_end"] = search_input.timestamp_end.isoformat()

        # Build QueryInput JSON for embed_search
        query_input_json = json.dumps({"params": query_params})

        try:
            embed_search_output = await embed_search.ainvoke(query_input_json)
        except ValueError as e:
            # Handle index not found or other validation errors from embed_search
            error_msg = str(e)
            logger.error(f"Embed search failed: {error_msg}")
            # Raise HTTPException for proper error response to client
            raise HTTPException(status_code=404, detail=error_msg) from e
        except Exception as e:
            # Handle other unexpected errors
            error_msg = str(e)
            status_code = 500

            # Try to extract status code from exception (works for Elasticsearch and other HTTP exceptions)
            if hasattr(e, "status_code"):
                status_code = e.status_code
            elif hasattr(e, "meta") and hasattr(e.meta, "status"):
                status_code = e.meta.status
            elif len(e.args) > 0 and isinstance(e.args[0], int):
                status_code = e.args[0]

            logger.error(f"Unexpected error in embed search: {error_msg}", exc_info=True)
            raise HTTPException(status_code=status_code, detail=f"Search error: {error_msg}") from e

        # Parse embed_search output (it returns a JSON string)
        if isinstance(embed_search_output, str):
            vision_llm = VisionLLM.model_validate_json(embed_search_output)
        elif isinstance(embed_search_output, VisionLLM):
            vision_llm = embed_search_output
        else:
            # Try to parse as dict
            vision_llm = VisionLLM.model_validate(embed_search_output)

        # Convert VisionLLM to SearchOutput
        search_results = []
        llm = vision_llm.llm
        base_timestamp = vision_llm.timestamp

        if not llm:
            return SearchOutput(data=[])

        for query in llm.queries:
            try:
                # Parse response JSON (handle empty/None safely)
                response_data = {}
                if query.response:
                    try:
                        parsed = json.loads(query.response)
                        response_data = parsed if isinstance(parsed, dict) else {}
                    except (json.JSONDecodeError, TypeError):
                        response_data = {}

                # Extract fields (handle None/empty values safely)
                sensor_description = ""
                if vision_llm.sensor:
                    sensor_description = vision_llm.sensor.description or ""

                video_name = response_data.get("video_name") or ""
                description = response_data.get("description") or sensor_description or ""
                video_url = response_data.get("video_url") or ""
                screenshot_url = response_data.get("screenshot_url") or "" or video_url
                similarity_score = response_data.get("similarity_score")
                if similarity_score is None:
                    similarity_score = 0.0
                else:
                    try:
                        similarity_score = float(similarity_score)
                    except (ValueError, TypeError):
                        similarity_score = 0.0

                # Skip if we don't have a valid video_name (empty string)
                if not video_name:
                    logger.warning(f"Skipping result with empty video_name: {response_data}")
                    continue

                # Convert start_time and end_time to ISO timestamp strings
                # Try to get base timestamp from response first, then from vision_llm_output
                response_timestamp = response_data.get("timestamp", "")
                base_timestamp_str = response_timestamp if response_timestamp else base_timestamp

                # Parse base timestamp
                base_dt: datetime | None = None
                if base_timestamp_str:
                    try:
                        base_dt = datetime.fromisoformat(str(base_timestamp_str).replace("Z", "+00:00"))
                    except Exception as e:
                        logger.debug(f"Failed to parse base timestamp '{base_timestamp_str}': {e}")

                # If no base timestamp, use current time
                if base_dt is None:
                    base_dt = datetime.now(UTC)

                # Ensure base_dt has timezone info
                if base_dt.tzinfo is None:
                    base_dt = base_dt.replace(tzinfo=UTC)

                # Handle start_time - can be float (seconds) or ISO string
                start_time_value = response_data.get("start_time", 0.0)
                if isinstance(start_time_value, str):
                    # Already an ISO string
                    try:
                        start_dt = datetime.fromisoformat(start_time_value.replace("Z", "+00:00"))
                        if start_dt.tzinfo is None:
                            start_dt = start_dt.replace(tzinfo=UTC)
                        start_time_iso = start_dt.isoformat().replace("+00:00", "Z")
                    except Exception as e:
                        logger.debug(f"Failed to parse start_time '{start_time_value}': {e}")
                        start_time_iso = base_dt.isoformat().replace("+00:00", "Z")
                elif isinstance(start_time_value, (int, float)):
                    # Float seconds - add to base timestamp
                    start_dt = base_dt + timedelta(seconds=float(start_time_value))
                    start_time_iso = start_dt.isoformat().replace("+00:00", "Z")
                else:
                    # Default to base timestamp
                    start_time_iso = base_dt.isoformat().replace("+00:00", "Z")

                # Handle end_time - can be float (seconds) or ISO string
                end_time_value = response_data.get("end_time", 0.0)
                if isinstance(end_time_value, str):
                    # Already an ISO string
                    try:
                        end_dt = datetime.fromisoformat(end_time_value.replace("Z", "+00:00"))
                        if end_dt.tzinfo is None:
                            end_dt = end_dt.replace(tzinfo=UTC)
                        end_time_iso = end_dt.isoformat().replace("+00:00", "Z")
                    except Exception as e:
                        logger.debug(f"Failed to parse end_time '{end_time_value}': {e}")
                        end_time_iso = base_dt.isoformat().replace("+00:00", "Z")
                elif isinstance(end_time_value, (int, float)):
                    # Float seconds - add to base timestamp
                    end_dt = base_dt + timedelta(seconds=float(end_time_value))
                    end_time_iso = end_dt.isoformat().replace("+00:00", "Z")
                else:
                    # Default to base timestamp
                    end_time_iso = base_dt.isoformat().replace("+00:00", "Z")

                # screenshot_url already extracted and translated above

                search_result = SearchResult(
                    video_name=video_name,
                    description=description,
                    start_time=start_time_iso,
                    end_time=end_time_iso,
                    video_url=video_url,
                    screenshot_url=screenshot_url,
                    similarity=float(similarity_score),
                )
                search_results.append(search_result)
            except Exception as e:
                logger.error(f"Error converting query result to SearchResult: {e}", exc_info=True)
                continue

        return SearchOutput(data=search_results)

    def _str_input_converter(input: str) -> SearchInput:
        """Convert string input (JSON) to SearchInput."""
        logger.info(f"String input: {input}")
        return SearchInput.model_validate_json(input)

    def _chat_request_input_converter(request: ChatRequest) -> SearchInput:
        """Convert ChatRequest to SearchInput from the last message content."""
        try:
            logger.info(f"Chat request input content: {request.messages[-1].content}")
            logger.info(f"Chat request input content type: {type(request.messages[-1].content)}")
            return SearchInput.model_validate_json(request.messages[-1].content)
        except Exception:
            logger.exception("Error in chat request input converter.")
            raise

    def _output_converter(output: SearchOutput) -> str:
        """Convert output to string JSON."""
        logger.info(f"Output: {output}")
        return output.model_dump_json()

    def _chat_response_output_converter(response: SearchOutput) -> ChatResponse:
        """Convert output to ChatResponse."""
        logger.info(f"Chat response output: {response}")
        return ChatResponse.from_string(_output_converter(response), usage=Usage())

    def _chat_response_chunk_output_converter(response: SearchOutput) -> ChatResponseChunk:
        """Convert output to ChatResponseChunk."""
        logger.info(f"Chat response chunk output: {response}")
        return ChatResponseChunk.from_string(_output_converter(response))

    yield FunctionInfo.create(
        single_fn=_search,
        description=_search.__doc__,
        input_schema=SearchInput,
        single_output_schema=SearchOutput,
        converters=[
            _str_input_converter,
            _chat_request_input_converter,
            _output_converter,
            _chat_response_output_converter,
            _chat_response_chunk_output_converter,
        ],
    )
